insert into public.routes (slug, name, name_en, region_id, difficulty, days_min, days_max, duration_hours, distance_km, elevation_gain_m, elevation_loss_m, max_altitude_m, min_altitude_m, route_type, season_months, tags, summary, description, difficulty_notes, getting_there, accommodation, water, permits, dangers, mobile_coverage, gear, tips, start_name, start_lat, start_lng, end_name, end_lat, end_lng, featured, status, sources) values
('omalo-shenako-diklo','ომალო – შენაქო – დიკლო','Omalo – Shenako – Diklo','tusheti','easy',1,1,4,11.2,660,380,2210,1670,'one_way','{6,7,8,9,10}'::smallint[],array['villages','history','towers','views']::text[],'ომალოდან შენაქოს ეკლესიის და დიკლოს ციხის ნანგრევებამდე — თუშეთის სახეობრივი დღე, დაღესტნის საზღვართან.','ქვემო ომალოდან ჩადიხარ ალაზანზე, შემდეგ შენაქოში ადიხარ — XIX საუკუნის ეკლესიითა და ქვის სახლებით. შენაქოდან ბილიკი დიკლომდე და კლდის ქიმზე შემორჩენილ დიკლოს ციხემდე მიდის, საიდანაც დაღესტნის მთები ჩანს.','ცალ მხარეს მარტივია. ფეხით დაბრუნებისას დღე ორმაგდება (~22 კმ) და საშუალო ხდება.','ომალომდე საზოგადოებრივი ტრანსპორტი არ დადის. თბილისიდან ქვემო ალვანამდე მარშრუტკით (~2 სთ), იქიდან 4x4 ჯიპით აბანოს უღელტეხილის გავლით (~4 სთ; 2026 წლის მონაცემით 100–120 ლარი ერთ მგზავრზე). გზა ჩვეულებრივ ივნისიდან ოქტომბრამდეა ღია და საქართველოს ერთ-ერთი ყველაზე სახიფათოა — მხოლოდ გამოცდილ ადგილობრივ მძღოლთან იარე. დიკლოდან ომალოში ჯიპით ბრუნდები (შეთანხმებით) ან ფეხით.','ომალოში, შენაქოსა და დიკლოში საოჯახო სასტუმროები.','გზაზე რამდენიმე ნაკადულია.','საშვი არ არის საჭირო, მაგრამ საზღვართან ახლოსაა — პასპორტი თან იქონიე.','მწყემსის ძაღლები ფარებთან. სალოცავებთან (მაგ. სალოცავი ნიშით) ქალების მისვლა ტრადიციით არ შეიძლება.','ნაწილობრივ.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH','ID']),array['გზად ''სიყვარულის ციხისკენ'' პატარა გადახვევა შეიძლება.']::text[],'ქვემო ომალო',42.37092,45.63308,'დიკლოს ციხე',42.3998,45.702,false,'published','https://www.caucasus-trekking.com/treks/omalodiklo'),
('tusheti-nakaicho-loop','თუშეთის ხეობების წრე (ნაკაიჩოს უღელტეხილი)','Tusheti valleys loop via Nakaicho pass','tusheti','moderate',3,3,null,57,2470,2470,2900,1650,'loop','{7,8,9}'::smallint[],array['villages','pass','towers','guesthouses','river_crossing']::text[],'სამდღიანი წრე ომალოდან: პირიქითა ხეობა, ნაკაიჩოს უღელტეხილი (~2 900 მ) და გომეწრის ხეობით დაბრუნება.','პირველ დღეს ომალოდან პირიქითა ალაზნის ხეობით დართლოსა და ჭეშომდე მიდიხარ. მეორე დღე წრის ყველაზე ლამაზი ნაწილია: ნაკაიჩოს (ნაკლე-ხოლის) უღელტეხილით გადადიხარ გომეწრის ხეობაში, ვერხოვანსა და ჯვარბოსელში. მესამე დღეს გომეწრის ხეობით ომალოში ბრუნდები.','პირველი და ბოლო დღე გრუნტის გზაა; მეორე დღე — უღელტეხილი და ნაკადულების სამჯერ გადალახვა.','ომალომდე საზოგადოებრივი ტრანსპორტი არ დადის. თბილისიდან ქვემო ალვანამდე მარშრუტკით (~2 სთ), იქიდან 4x4 ჯიპით აბანოს უღელტეხილის გავლით (~4 სთ; 2026 წლის მონაცემით 100–120 ლარი ერთ მგზავრზე). გზა ჩვეულებრივ ივნისიდან ოქტომბრამდეა ღია და საქართველოს ერთ-ერთი ყველაზე სახიფათოა — მხოლოდ გამოცდილ ადგილობრივ მძღოლთან იარე.','ომალოში, დართლოში, ჭეშოში და ჯვარბოსელში/ვერხოვანში — საოჯახო სასტუმროები (ზოგ სოფელში ძალიან ცოტა).','ნაკადულები ბევრია.','არ არის საჭირო.','წვიმის შემდეგ ნაკადულები მატულობს. ზოგიერთი ხიდი დანგრეულია — ადგილზე იკითხე. მწყემსის ძაღლები.','სოფლებში ნაწილობრივ, უღელტეხილზე — არა.',seed.gear(array['BOOTS','BACKPACK_MULTI','RAIN','FLEECE','HAT_GLOVES','SUN','WATER_2','FILTER','SNACKS','FIRST_AID','OFFLINE_MAP','POLES_REQ','HEADLAMP','POWERBANK','CASH','TRASH','SANDALS']),array['გომეწრის ხეობაში ღამის გასათევი წინასწარ დაჯავშნე — სასტუმრო ცოტაა.']::text[],'ომალო',42.37092,45.63308,'ომალო',42.37092,45.63308,false,'published','https://www.caucasus-trekking.com/treks/nakle'),
('black-rock-lake','ლაგოდეხი – შავი კლდეების ტბა','Lagodekhi – Black Rock Lake','kakheti','hard',2,3,null,38,2890,2890,2860,570,'loop','{6,7,8,9}'::smallint[],array['lakes','forest','wildlife','huts','national_park','border_zone']::text[],'ლაგოდეხის ეროვნული პარკის ცნობილი ტრეკი: კოლხური ტყიდან ალპურ ზონამდე, შავი კლდეების ტბამდე დაღესტნის საზღვარზე.','ლაგოდეხის ვიზიტორთა ცენტრიდან (~570 მ) პირველ დღეს ტყით ~1 500 მ ადიხარ მეტეოს თავშესაფრამდე. მეორე დღეს ალპური მდელოებით, ქედზე შავი კლდეების ტბამდე (~2 850 მ) მიდიხარ — ტბა საქართველო–რუსეთის (დაღესტნის) საზღვარზეა. ღამე დემიდოვოს თავშესაფარში, მესამე დღეს კი ~2 100 მ დაღმართით ლაგოდეხში ბრუნდები. ტყეში ირემი, არჩვი და ჯიხვია.','პირველ დღეს ~1 500 მ განუწყვეტელი აღმართია, ბოლო დღეს — ~2 100 მ დაღმართი. ფიზიკურად ძალიან დამღლელი, თუმცა ტექნიკური ადგილები არ არის.','ლაგოდეხამდე თბილისიდან მარშრუტკა ისნის სადგურიდან (~2.5 სთ; 2026 წლის მონაცემით ~15 ლარი, დილიდან საღამომდე). ვიზიტორთა ცენტრი ქალაქშია.','მეტეოს და დემიდოვოს თავშესაფრები (საწოლებით; 2026 წლის მონაცემით ~30 ლარი ღამე) ან კარვის ადგილი (~5 ლარი).','თავშესაფრებთან და მონიშნულ წყაროებთან. ზაფხულის ბოლოს ზოგი წყარო შრება.','გასვლამდე დარეგისტრირდი ლაგოდეხის დაცული ტერიტორიების ადმინისტრაციაში. ტბასთან სასაზღვრო პოსტია — პასპორტი ან პირადობა აუცილებელია.','წვიმის შემდეგ ტყის ბილიკი ძალიან მოლიპულია. ~910 მ სიმაღლეზე ბილიკები იყოფა — რუკას დახედე. ზემოთ ნისლი და სიცივე.','ქვედა ნაწილში არის, ზემოთ — სუსტი.',seed.gear(array['BOOTS','BACKPACK_MULTI','RAIN','FLEECE','HAT_GLOVES','SUN','WATER_2','FILTER','SNACKS','FIRST_AID','OFFLINE_MAP','POLES_REQ','HEADLAMP','POWERBANK','CASH','TRASH','SLEEPING_BAG','FOOD_DAYS','ID']),array['ძლიერი მოლაშქრეები ორ დღეში ასრულებენ, მაგრამ სამი დღე ბევრად სასიამოვნოა.','თავშესაფარში ადგილი წინასწარ დაჯავშნე ადმინისტრაციის გავლით.']::text[],'ლაგოდეხის ვიზიტორთა ცენტრი',41.84213,46.28253,'ლაგოდეხი',41.84213,46.28253,true,'published','https://www.caucasus-trekking.com/treks/trek-to-the-black-rock-lake ; https://apa.gov.ge/en/eco-tourism/Trails/lagodexis-daculi-teritoriebis-turistuli-bilikebi/4-shvi-kldeebis-tba'),
('ninoskhevi-waterfall','ნინოსხევის ჩანჩქერი (ლაგოდეხი)','Ninoskhevi waterfall, Lagodekhi','kakheti','easy',1,1,4,8.5,250,250,800,550,'out_and_back','{4,5,6,7,8,9,10,11}'::smallint[],array['waterfall','forest','family','national_park','river_crossing']::text[],'ლაგოდეხის კოლხურ ტყეში ნინოსხევის ხეობით 40-მეტრიან ჩანჩქერამდე — მარტივი და ძალიან ლამაზი ოჯახური ლაშქრობა.','ბილიკი გურგენიანის სადარაჯოდან ტყეში შედის და ნინოსხევის ნაკადულს მიუყვება, რამდენჯერმე გადაკვეთს მას ქვებზე ან პატარა ხიდებზე. ბოლოს ვიწრო ხეობაში 40 მეტრიანი ჩანჩქერი ჩნდება. ზაფხულის სიცხეში აქ საოცრად გრილა.','მცირე აღმართი, მაგრამ ნაკადულის რამდენჯერმე გადალახვა სველ ქვებზე.','ლაგოდეხამდე თბილისიდან მარშრუტკით ისნის სადგურიდან (~2.5 სთ), იქიდან გურგენიანის სადარაჯომდე ტაქსით (~15 წთ).',null,'ნაკადული გვერდითაა.','დარეგისტრირდი ლაგოდეხის დაცული ტერიტორიების ადმინისტრაციაში.','ძლიერი წვიმის შემდეგ ნაკადულის გადალახვა რთულდება. ქვები მოლიპულია.','ქვედა ნაწილში არის.',seed.gear(array['SHOES_LIGHT','WATER_1','SUN','RAIN','SNACKS','FIRST_AID','TRASH','SANDALS']),array['ფეხსაცმელი, რომელიც არ გეწყინება რომ დასველდეს, ან სანდლები — ბილიკი ბევრჯერ კვეთს ნაკადულს.']::text[],'გურგენიანის სადარაჯო',41.87301,46.23946,'ნინოსხევის ჩანჩქერი',41.89764,46.26784,false,'published','https://georgia.to/trails-of-lagodekhi-protected-areas/'),
('machi-fortress','მაჭის ციხე (ლაგოდეხი)','Machi fortress, Lagodekhi','kakheti','easy',1,1,4,10.5,400,400,850,450,'out_and_back','{3,4,5,6,7,8,9,10,11}'::smallint[],array['history','forest','national_park']::text[],'ტყიანი ბილიკი შუასაუკუნეების მაჭის ციხემდე — კედლები, საგვარეულო ეკლესია და მიწისქვეშა სავალები ლაგოდეხის ტყეში.','სოფელ მაწიმიდან ბილიკი ტყით ადის მაჭის ციხის ნანგრევებამდე, რომელიც ალაზნის ველს გადაჰყურებს. ციხე კარგად შემორჩენილია: კედლები, კოშკები, ეკლესია.','ზომიერი აღმართი ტყეში.','ბილიკის დასაწყისი სოფელ მაწიმთანაა, ლაგოდეხის ადმინისტრაციიდან ~7 კმ-ში (ტაქსით).',null,'წყალი თან წაიღე.','დარეგისტრირდი ლაგოდეხის ვიზიტორთა ცენტრში.','ციხის კედლებზე ნუ ახვალ — ნანგრევებია.','უმეტესად არის.',seed.gear(array['SHOES_LIGHT','WATER_1','SUN','RAIN','SNACKS','FIRST_AID','TRASH']),array['გაზაფხულზე და შემოდგომაზე ყველაზე სასიამოვნოა — ზაფხულში ქვემოთ ცხელა.']::text[],'მაჭის ციხის ბილიკის დასაწყისი (მაწიმი)',41.80935,46.31026,'მაჭის ციხე',41.82141,46.35383,false,'published','https://georgia.to/trails-of-lagodekhi-protected-areas/'),
('vashlovani-national-park','ვაშლოვანის ეროვნული პარკი','Vashlovani National Park','kakheti','moderate',2,2,null,120,900,900,900,150,'loop','{4,5,6,9,10,11}'::smallint[],array['4x4','canyon','wildlife','camping','national_park','border_zone']::text[],'ნახევრად უდაბნო, ფერადი ხეობები, არწივის ხეობა და ალაზნის ჭალა აზერბაიჯანის საზღვართან — 4x4 მანქანით და მოკლე ლაშქრობებით.','ვაშლოვანი საქართველოს ''სავანაა'': მშრალი ღია ტყეები, ტალახის ვულკანები, მიწის ''არეულები'' და ღრმა კანიონები. პარკში მოძრაობა მხოლოდ 4x4 მანქანით შეიძლება — ფეხით მოკლე ლაშქრობები არწივის ხეობასა და სხვა ხეობებში კეთდება. ღამე პარკის კოტეჯებში ან ბანაკში (მაგ. მიჯნისყურე, ალაზნის ჭალა) ათევ.','ფიზიკურად მარტივია, მაგრამ მოშორებული ტერიტორიაა: სიცხე, ცუდი გზები და წყლის ნაკლებობა.','დედოფლისწყარომდე თბილისიდან (~2.5 სთ). პარკში შესვლა მხოლოდ 4x4 მანქანით; ადგილობრივ ჯიპს დედოფლისწყაროში იქირავებ.','პარკის კოტეჯები და ბანაკები (2026 წლის მონაცემით კოტეჯი 40–60 ლარი, კარავი ~5 ლარი ადამიანზე).','პარკში წყალი თითქმის არ არის — ორი დღის მარაგი და საწვავი თან იქონიე.','დედოფლისწყაროს ვიზიტორთა ცენტრში წინასწარ რეგისტრაცია და პირადობის ასლი აუცილებელია (სასაზღვრო ტერიტორიაა). შესვლის საფასური ~5 ლარი თითო ლოკაციაზე.','ზაფხულში (ივლისი–აგვისტო) უკიდურესი სიცხეა. გველები (მათ შორის გიურზა) — ფეხსაცმელი და გრძელი შარვალი. წვიმის შემდეგ თიხის გზები გაუვალი ხდება.','უმეტეს ნაწილში არ არის.',seed.gear(array['SHOES_LIGHT','BOOTS','WATER_2','SUN','FIRST_AID','OFFLINE_MAP','CASH','ID','TENT','FOOD_DAYS','HEADLAMP','TRASH','INSECT']),array['საუკეთესო დრო — აპრილი–მაისი (ყვავილობა) და ოქტომბერი.','ფრინველებზე დასაკვირვებლად აპრილი და ოქტომბერ–ნოემბერია საუკეთესო.']::text[],'დედოფლისწყაროს ვიზიტორთა ცენტრი',41.46396,46.11041,'დედოფლისწყარო',41.46396,46.11041,false,'published','https://www.apa.gov.ge/en/eco-tourism/servisebi-da-tarifebi/VashlovaniProtectedAreas')
